<?php

namespace Database\Seeders;

use Database\Seeders\Concerns\LoadsTestProductionData;
use Database\Seeders\Support\TestProductionLinks;
use Illuminate\Database\Seeder;
use Illuminate\Support\Facades\Schema;

/**
 * The engineering side of the test production dataset: routings with their operations, materials and approvals,
 * and bills of materials with their items and approvals. Same conventions as TestProductionMasterDataSeeder
 * (natural keys for units, branches ...; own ids kept).
 */
class TestProductionEngineeringSeeder extends Seeder
{
    use LoadsTestProductionData;

    public function run(?int $tenantId = null): void
    {
        $tenantId = $this->resolveTenantId($tenantId);
        $links = new TestProductionLinks($tenantId);

        Schema::disableForeignKeyConstraints();

        try {
            foreach ($this->tables() as $table => $rows) {
                $this->seedTable($table, $rows, $tenantId, $links);
            }
        } finally {
            Schema::enableForeignKeyConstraints();
        }

        $this->command?->info("TestProductionEngineeringSeeder completed successfully for Tenant ID {$tenantId}.");
    }

    /**
     * Routings and bills of materials.
     *
     * @return array<string, array<int, array<string, mixed>>> table => rows, in the order they are loaded
     */
    public function tables(): array
    {
        return [
            'routings' => $this->routings(),
            'production_routing_operations' => $this->productionRoutingOperations(),
            'production_routing_operation_materials' => $this->productionRoutingOperationMaterials(),
            'production_routing_approvals' => $this->productionRoutingApprovals(),
            'production_boms' => $this->productionBoms(),
            'production_bom_items' => $this->productionBomItems(),
            'production_bom_approvals' => $this->productionBomApprovals(),
        ];
    }

